tool.command:

#if $input_trajectory_path:
  ln -s $input_trajectory_path ./input_trajectory_path.$input_trajectory_path.ext;
#end if
ln -s $input_topology_path ./input_topology_path.$input_topology_path.ext;
#if $config_json:
  ln -s $config_json ./config_json.$config_json.ext;
#end if

mdfeaturizer

#if $config_json:
  --config ./config_json.$config_json.ext
#end if

#if $input_trajectory_path:
  --input_trajectory_path ./input_trajectory_path.$input_trajectory_path.ext
#end if
--input_topology_path ./input_topology_path.$input_topology_path.ext
--output_dataset_pt_path $outname_output_dataset_pt_path
--output_stats_pt_path $outname_output_stats_pt_path
;

mv $outname_output_dataset_pt_path $output_dataset_pt_path;
mv $outname_output_stats_pt_path $output_stats_pt_path;
